window.__ModuleLoader__.load({
 id:"@deepseek-ai/dsh-client-ui-workbench",
 factory:(require)=>{
  const React=require("react"),jsx=require("react/jsx-runtime");

  const zh={"settings.nav":"目录与运行环境"};
  const css=`.dsh-path-settings{height:100%;overflow:auto;padding:24px max(24px,5vw);background:var(--dsw-alias-bg-base);color:var(--dsw-alias-label-primary)}.dsh-path-settings h2{margin:0 0 24px;font-size:18px;font-weight:550}.dsh-path-row{display:grid;grid-template-columns:120px minmax(0,1fr) auto;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid var(--dsw-alias-border-l2)}.dsh-path-label{color:var(--dsw-alias-label-secondary)}.dsh-path-value{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--dsw-alias-label-primary)}.dsh-path-button{height:32px;padding:0 14px;border:1px solid var(--dsw-alias-border-l2);border-radius:8px;background:var(--dsw-alias-bg-base);color:var(--dsw-alias-label-primary);font:inherit;cursor:pointer}.dsh-path-button:hover{background:var(--dsw-alias-interactive-bg-hover)}.dsh-path-actions{display:flex;align-items:center;gap:12px;margin-top:20px}.dsh-path-primary{background:var(--dsw-alias-interactive-bg-primary);color:var(--dsw-alias-label-on-color)}.dsh-path-note,.dsh-path-status{font-size:12px;color:var(--dsw-alias-label-tertiary)}.dsh-path-status[data-error=true]{color:var(--dsw-alias-state-error-primary)}`;
  function installCss(){if(document.querySelector("style[data-dsh-path-settings]"))return;const s=document.createElement("style");s.dataset.dshPathSettings="";s.textContent=css;document.head.appendChild(s)}
  function ContextSettings({api,renderSlot}){
   const [data,setData]=React.useState(null),[status,setStatus]=React.useState(""),[error,setError]=React.useState(false),[picking,setPicking]=React.useState(null);
   React.useEffect(()=>{let live=true;Promise.all([api?.host?.describe?.({}),api?.settings?.describe?.({})]).then(([h,s])=>{if(!live)return;const namespaces=s?.result?.ok?s.result.value.namespaces??[]:[];const paths=namespaces.find(x=>x.ns==="storage-paths")?.value??{};setData({environmentDirectory:paths.environmentDirectory??"",dataDirectory:paths.dataDirectory??""})}).catch(e=>{setError(true);setStatus(String(e))});return()=>{live=false}},[api]);
   const save=()=>{setError(false);setStatus("正在保存…");api?.settings?.update?.({ns:"storage-paths",patch:{environmentDirectory:data.environmentDirectory}}).then(r=>{if(r?.result?.ok)setStatus("已保存");else{setError(true);setStatus("保存失败："+(r?.result?.error?.message??"未知错误"))}}).catch(e=>{setError(true);setStatus("保存失败："+String(e))})};
   const select=path=>{if(picking)setData(current=>({...current,[picking]:path}));setPicking(null)};
   const rows=[["环境目录","environmentDirectory"]];
   const flow=picking?renderSlot("settings.paths.directoryFlow",{open:true,busy:false,onPicked:select,onCancel:()=>setPicking(null),onError:e=>{setError(true);setStatus(String(e));setPicking(null)}}):null;
   return jsx.jsxs("section",{className:"dsh-path-settings",children:[jsx.jsx("h2",{children:"目录与运行环境"}),data===null?jsx.jsx("div",{className:"dsh-path-note",children:"正在读取…"}):jsx.jsxs(jsx.Fragment,{children:[rows.map(([label,key])=>jsx.jsxs("div",{className:"dsh-path-row",children:[jsx.jsx("span",{className:"dsh-path-label",children:label}),jsx.jsx("span",{className:"dsh-path-value",title:data[key]||"未选择",children:data[key]||"未选择"}),jsx.jsx("button",{type:"button",className:"dsh-path-button",onClick:()=>setPicking(key),children:"选择"})]},key)),jsx.jsxs("div",{className:"dsh-path-row",children:[jsx.jsx("span",{className:"dsh-path-label",children:"数据目录"}),jsx.jsx("span",{className:"dsh-path-value",title:data.dataDirectory||"未配置",children:data.dataDirectory||"未配置"}),jsx.jsx("span",{className:"dsh-path-note",children:"当前运行根"})]}),jsx.jsxs("div",{className:"dsh-path-actions",children:[jsx.jsx("button",{type:"button",className:"dsh-path-button dsh-path-primary",onClick:save,children:"保存"}),status&&jsx.jsx("span",{role:"status",className:"dsh-path-status","data-error":error||void 0,children:status})]})]}),flow]})
  }
  function apply(ctx){installCss();ctx.effect(()=>ctx.locale.register("workbench",{zh}),"directory settings locale");ctx.slots.inject("settings.section",()=>ctx.slots.register({name:"settings.section",id:"workbench-context",order:15,label:"目录与运行环境",children:{"settings.paths.directoryFlow":{kind:"single",scope:"root"}}},({renderSlot})=>jsx.jsx(ContextSettings,{api:ctx.get("connection")?.api,renderSlot})))}
  return {apply,inject:["slots","locale","connection"]}
 }
});
